import{_ as l,a0 as o,w as d,s as n,ao as r,I as p,x as s,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"為你的 Fedora 系統增添發音功能 | LCTT x X-CMD","titleTemplate":false,"description":"為你的 Fedora 系統增添發音功能 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為你的 Fedora 系統增添發音功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為你的 Fedora 系統增添發音功能 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170804 Add speech to your Fedora system","title":"為你的 Fedora 系統增添發音功能","tag":"201801","desc":""},"relativePath":"201801/20170804 Add speech to your Fedora system.md","filePath":"[post].md"}'),h={name:"201801/20170804 Add speech to your Fedora system.md"};function g(k,e,u,f,c,b){const a=o("Link");return d(),n("div",null,[e[13]||(e[13]=r('<h1 id="為你的-fedora-系統增添發音功能" tabindex="-1">為你的 Fedora 系統增添發音功能 <a class="header-anchor" href="#為你的-fedora-系統增添發音功能" aria-label="Permalink to “為你的 Fedora 系統增添發音功能”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/08/espeak-945x400.png" alt=""></p><p>Fedora 工作站默認帶有一個小軟件，叫做 espeak。它是一個聲音合成器 -- 也就是轉換文本為聲音的軟件。</p><p>在當今這個世界，發音設備已經非常普遍了。在智能電話、Amazon Alexa，甚至火車站的公告欄中都有聲音合成器。而且，現在合成聲音已經跟人類的聲音很類似了。我們生活在 80bandaid 的科幻電影裏！</p><p>與前面提到的這些工具相比，espeak 的發音聽起來有一點原始。但最終 espeak 可以產生不錯的發音效果。而且不管你覺得它有沒有用，至少它可以給你帶來一些樂趣。</p><h3 id="運行-espeak" tabindex="-1">運行 espeak <a class="header-anchor" href="#運行-espeak" aria-label="Permalink to “運行 espeak”">​</a></h3><p>你可以在命令列為 espeak 設置各種參數。包括：</p><ul><li>振幅（<code>-a</code>）</li><li>音高調整 （<code>-p</code>）</li><li>讀句子的速度 （<code>-s</code>）</li><li>單詞間的停頓時間 （<code>-g</code>）</li></ul><p>每個選項都能產生不同的效果，你可以通過調整它們來讓發音更加清晰。</p><p>你也可以通過命令列選項來選擇不同的變音。比如，<code>-ven+m3</code> 表示另一種英式男音，而 <code>-ven+f1</code> 表示英式女音。你也可以嘗試其他語言的發音。運行下面命令可以查看支持的語言列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>espeak --voices</span></span></code></pre></div><p>要注意，很多非英語的語言發音現在還處於實驗階段。</p><p>若要創建相應的 WAV 文件而不是真的講出來，則可以使用 <code>-w</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>espeak -w out.wav &quot;Audio file test&quot;</span></span></code></pre></div><p>espeak 還能讀出文件的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>espeak -f plaintextfile</span></span></code></pre></div><p>你也可以通過標準輸入傳遞要發音的文本。舉個簡單的例子，通過這種方式，你可以創建一個發音盒子，當事件發生時使用聲音通知你。你的備份完成了？將下面命令添加到腳本的最後試試效果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;Backup completed&quot; | espeak -s 160 -a 100 -g 4</span></span></code></pre></div><p>假如有日誌文件中出現錯誤了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -1F /your/log/file | grep --line-buffered &#39;ERROR&#39; | espeak</span></span></code></pre></div><p>或者你也可以創建一個報時鐘表，每分鐘報一次時：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>while true; do date +%S | grep &#39;00&#39; &amp;&amp; date +%H：%M | espeak; sleep 1; done</span></span></code></pre></div><p>你會發現，espeak 的使用場景僅僅受你的想像所限制。享受你這會發音的 Fedora 系統吧！</p><hr>',24)),p("p",null,[e[1]||(e[1]=s("via: ",-1)),t(a,{href:"https://fedoramagazine.org/add-speech-fedora-system/"},{default:i(()=>[...e[0]||(e[0]=[s("https://fedoramagazine.org/add-speech-fedora-system/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=s("作者：",-1)),t(a,{href:"http://alciregi.id.fedoraproject.org/"},{default:i(()=>[...e[2]||(e[2]=[s("Alessio Ciregia",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const x=l(h,[["render",g]]);export{C as __pageData,x as default};
